Com números:

```
const notas = [7, 8, 5];

// Tem alguém reprovado (nota abaixo de 6)?
notas.some((n) => n < 6);  // true — o 5 reprova

// TODOS passaram (nota 6 ou mais)?
notas.every((n) => n >= 6); // false — o 5 derruba
```

Com objetos:

```
const convidados = [
  { nome: 'Ana', confirmou: true },
  { nome: 'Beto', confirmou: false }
];

convidados.every((c) => c.confirmou === true); // false — Beto não confirmou
convidados.some((c) => c.confirmou === true);  // true — Ana confirmou
```

Regra de bolso: `some` para no SIM, `every` para no NÃO. Os dois só percorrem a lista inteira quando precisam — o `some` vira falso e o `every` vira verdadeiro.

code.code:
// Passo 1: conferimos que veio uma lista de verdade.
function statusDaFesta(convidados) {
  if (!Array.isArray(convidados)) {
    throw new Error('convidados precisa ser uma lista');
  }

  // Passos 2 e 3: as duas perguntas de sim/não.
  return {
    todosConfirmaram: convidados.every((c) => c.confirmou === true),
    algumTrazBebida: convidados.some((c) => c.trazBebida === true),
  };
}

const lista = [
  { nome: 'Ana', confirmou: true, trazBebida: false },
  { nome: 'Beto', confirmou: true, trazBebida: true }
];

console.log(statusDaFesta(lista));
// imprime: { todosConfirmaram: true, algumTrazBebida: true }
